"""Runs MediaMTX (the media server spokes publish to) and tracks which streams are up

Paths:
    spoke/<id>    a spoke that is live: recorded, and restreamed to its destinations
    preview/<id>  a spoke sending a preview: shown in the dashboard only
"""
import json
import os
import subprocess
import threading
import time
import urllib.request

from . import settings

CONFIG = """\
# Generated by TouchStream Hub - edits are overwritten on start
logLevel: info
logDestinations: [stdout]

authMethod: http
authHTTPAddress: http://127.0.0.1:{http_port}/api/internal/mediamtx-auth
authHTTPExclude:
  - action: api
  - action: metrics
  - action: pprof

api: true
apiAddress: 127.0.0.1:{api_port}

# Internal only: the hub's restreamers read HLS (it keeps the spoke's timestamps: RTSP puts sound and
# picture out of step), made as soon as a stream arrives so a broadcast starts at once; the dashboard
# plays it through the hub
rtsp: true
rtspTransports: [tcp]
rtspAddress: 127.0.0.1:{rtsp_port}
hls: true
hlsAddress: 127.0.0.1:{hls_port}
hlsVariant: mpegts
hlsAlwaysRemux: true
webrtc: false
moq: false

# Public ingest: spokes publish over SRT, other encoders (OBS, ATEM) can use RTMP
srt: true
srtAddress: :{srt_port}
rtmp: true
rtmpAddress: :{rtmp_port}

pathDefaults:
  record: false
  recordPath: {record_path}
  recordFormat: fmp4
  recordSegmentDuration: 1h
  recordDeleteAfter: 0s

paths:
  "~^spoke/[A-Za-z0-9]+$":
    record: true
  "~^preview/[A-Za-z0-9]+$":
    record: false
"""


class MediaMTX:
    def __init__(self):
        self.proc = None
        self.paths = {}          # path name -> MediaMTX path info, for paths with a publisher
        self.available = os.path.exists(settings.MEDIAMTX_BIN)
        self._stopping = False

    def config_path(self):
        return settings.DATA_DIR / 'mediamtx.yml'

    def write_config(self):
        # MediaMTX wants forward slashes, even on Windows; JSON quoting is valid YAML
        recordings = str(settings.RECORDINGS_DIR).replace('\\', '/')
        self.config_path().write_text(CONFIG.format(
            http_port=settings.HTTP_PORT, api_port=settings.MTX_API_PORT,
            rtsp_port=settings.MTX_RTSP_PORT, hls_port=settings.MTX_HLS_PORT,
            srt_port=settings.SRT_PORT, rtmp_port=settings.RTMP_PORT,
            record_path=json.dumps(f'{recordings}/%path/hub/%Y-%m-%d_%H-%M-%S-%f_%z')))

    def start(self):
        if not self.available:
            print(f"MediaMTX not found at {settings.MEDIAMTX_BIN}; streaming is disabled "
                  "(set TOUCHSTREAM_MEDIAMTX or install mediamtx)")
            return
        self.write_config()
        threading.Thread(target=self._supervise, daemon=True).start()
        threading.Thread(target=self._poll, daemon=True).start()

    def stop(self):
        self._stopping = True
        if self.proc and self.proc.poll() is None:
            self.proc.terminate()

    def _supervise(self):
        while not self._stopping:
            print("Starting MediaMTX")
            # Run inside the data folder: MediaMTX writes files (e.g. a self-signed
            # certificate) to its working directory
            self.proc = subprocess.Popen([settings.MEDIAMTX_BIN, str(self.config_path())],
                                         cwd=settings.DATA_DIR, stdout=subprocess.PIPE,
                                         stderr=subprocess.STDOUT, text=True)
            for line in self.proc.stdout:
                print(f"[mediamtx] {line.rstrip()}")
            self.proc.wait()
            if not self._stopping:
                print(f"MediaMTX exited ({self.proc.returncode}); restarting in 3s")
                time.sleep(3)

    def _poll(self):
        url = f'http://127.0.0.1:{settings.MTX_API_PORT}/v3/paths/list?itemsPerPage=1000'
        while not self._stopping:
            try:
                with urllib.request.urlopen(url, timeout=3) as resp:
                    items = json.load(resp).get('items', [])
                self.paths = {p['name']: p for p in items if p.get('ready')}
            except Exception:
                self.paths = {}
            time.sleep(2)

    def ready(self, path):
        return path in self.paths

    def source_info(self, path):
        """Codec summary of a ready path, e.g. ['H264', 'MPEG-4 Audio']."""
        info = self.paths.get(path)
        return info.get('tracks', []) if info else []
